import React, { useState, useEffect, useRef } from 'react';

const StockSearch = ({ onSelectStock }) => {
    const [query, setQuery] = useState('');
    const [suggestions, setSuggestions] = useState([]);
    const [loading, setLoading] = useState(false);
    const [showSuggestions, setShowSuggestions] = useState(false);
    const wrapperRef = useRef(null);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const searchStocks = async (searchQuery) => {
        if (!searchQuery || searchQuery.length < 1) {
            setSuggestions([]);
            setShowSuggestions(false);
            return;
        }

        setLoading(true);
        try {
            const response = await fetch(
                `http://localhost:5000/api/search/${searchQuery}`
            );
            const data = await response.json();
            setSuggestions(data || []);
            setShowSuggestions(true);
        } catch (error) {
            console.error('Error searching stocks:', error);
            setSuggestions([]);
        }
        setLoading(false);
    };

    const handleInputChange = (e) => {
        const value = e.target.value.toUpperCase();
        setQuery(value);
        searchStocks(value);
    };

    const handleSelect = (symbol) => {
        setQuery(symbol);
        setShowSuggestions(false);
        onSelectStock(symbol);
    };

    return (
        <div ref={wrapperRef} style={{ position: 'relative', width: '100%' }}>
            <div style={{ position: 'relative' }}>
                <input
                    type="text"
                    placeholder="🔍 Search stocks (e.g., RELIANCE, TCS, HDFCBANK)"
                    value={query}
                    onChange={handleInputChange}
                    onFocus={() => query.length >= 1 && setShowSuggestions(true)}
                    style={{
                        width: '100%',
                        padding: '14px 20px',
                        paddingRight: '40px',
                        background: '#1a2332',
                        border: '2px solid #2a3a5c',
                        borderRadius: '10px',
                        color: 'white',
                        fontSize: '16px',
                        outline: 'none',
                        transition: 'border-color 0.2s'
                    }}
                />
                {loading && (
                    <div style={{
                        position: 'absolute',
                        right: '15px',
                        top: '50%',
                        transform: 'translateY(-50%)',
                        color: '#8a9bb5'
                    }}>
                        ⏳
                    </div>
                )}
            </div>

            {showSuggestions && suggestions.length > 0 && (
                <div style={{
                    position: 'absolute',
                    top: '100%',
                    left: 0,
                    right: 0,
                    marginTop: '4px',
                    background: '#141b2b',
                    border: '1px solid #2a3a5c',
                    borderRadius: '10px',
                    maxHeight: '400px',
                    overflowY: 'auto',
                    zIndex: 1000,
                    boxShadow: '0 10px 40px rgba(0,0,0,0.5)'
                }}>
                    {suggestions.map((stock) => (
                        <div
                            key={stock.symbol}
                            onClick={() => handleSelect(stock.symbol)}
                            style={{
                                padding: '12px 16px',
                                cursor: 'pointer',
                                borderBottom: '1px solid #2a3a5c',
                                transition: 'background 0.2s',
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center'
                            }}
                            onMouseEnter={(e) => e.target.style.background = '#1a2332'}
                            onMouseLeave={(e) => e.target.style.background = 'transparent'}
                        >
                            <div>
                                <div style={{ fontWeight: 'bold', fontSize: '16px', color: '#e0e6ed' }}>
                                    {stock.symbol}
                                </div>
                                <div style={{ fontSize: '13px', color: '#8a9bb5' }}>
                                    {stock.name}
                                </div>
                            </div>
                            <div style={{ textAlign: 'right' }}>
                                {stock.price ? (
                                    <>
                                        <div style={{ fontWeight: 'bold', fontSize: '16px', color: '#e0e6ed' }}>
                                            ₹{stock.price.toFixed(2)}
                                        </div>
                                        {stock.change_percent !== null && (
                                            <div style={{
                                                fontSize: '13px',
                                                color: stock.change_percent >= 0 ? '#4CAF50' : '#dc3545',
                                                fontWeight: 'bold'
                                            }}>
                                                {stock.change_percent >= 0 ? '+' : ''}{stock.change_percent.toFixed(2)}%
                                            </div>
                                        )}
                                    </>
                                ) : (
                                    <div style={{ color: '#8a9bb5', fontSize: '13px' }}>Loading...</div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {showSuggestions && query.length >= 1 && suggestions.length === 0 && !loading && (
                <div style={{
                    position: 'absolute',
                    top: '100%',
                    left: 0,
                    right: 0,
                    marginTop: '4px',
                    padding: '15px',
                    background: '#141b2b',
                    border: '1px solid #2a3a5c',
                    borderRadius: '10px',
                    color: '#8a9bb5',
                    textAlign: 'center'
                }}>
                    No stocks found. Try searching with a different symbol or name.
                </div>
            )}
        </div>
    );
};

export default StockSearch;
